window.MGProseData("2e0a7d1226deadcb68635ddee7e9d83a22ba52f85bd83cf2515519ebd9af1fca",{"html":"\u003ch2>S1 可缩子复形的商\u003c/h2>\n\u003cp>\u003cstrong>结论：商映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q:Y\\to Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是同伦等价。\u003c/strong>\u003c/p>\n\u003cp>因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(Y,A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 CW 对，包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\\hookrightarrow Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 具有同伦延拓性质。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的收缩\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nc_t:A\\to A,\\qquad c_0=\\operatorname{id}_A,\\qquad c_1(a)=a_0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并把它延拓为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF_t:Y\\to Y,\\qquad F_0=\\operatorname{id}_Y,\\qquad F_t|_A=c_t.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_t(A)\\subseteq A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_1(A)=\\{a_0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在商空间上定义了连续映射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>g\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng:Y/A\\longrightarrow Y,\\qquad g([y])=F_1(y).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n显然 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">gq=F_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmi>g\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{id}_Y\\simeq gq.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>另一方面，对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">qF_t:Y\\to Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 映到同一个点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[A]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，因而下降为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline F_t:Y/A\\longrightarrow Y/A,\\qquad \\overline F_t([y])=[F_t(y)].\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\overline F_0=\\operatorname{id}_{Y/A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\overline F_1=qg\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi>g\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{id}_{Y/A}\\simeq qg.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n下降后的同伦连续，是因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>×\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\times\\operatorname{id}_{[0,1]}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是商映射（区间是局部紧致空间）。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的同伦逆。\u003c/p>\n\u003chr>\n\u003ch2>S2 非可缩底空间上的锥附着\u003c/h2>\n\u003cp>记映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f:L\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的非约化映射锥为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC(f)=D\\cup_f CL.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n我们用以下标准事实：对于 CW 空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f_0\\simeq f_1:L\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC(f_0)\\simeq C(f_1).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是映射锥作为同伦推出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>⟵\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmo>∗\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nD\\longleftarrow L\\longrightarrow *\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n的同伦不变性；此处 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\\hookrightarrow CL\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是余纤维，故普通推出就是相应的同伦推出。\u003c/p>\n\u003cp>也可以直接写出映射：若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H:f_0\\simeq f_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>f\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F:C(f_0)\\to C(f_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为恒等，在锥上为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF(x,t)=\n\\begin{cases}\nH(x,2t)\\in D,\u0026amp;0\\le t\\le \\frac12,\\\\[2mm]\n(x,2t-1)\\in CL,\u0026amp;\\frac12\\le t\\le1 .\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的反向同伦类似构造反向映射；拼接 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与其反向同伦并重新参数化锥坐标，可得两个复合均同伦于恒等。\u003c/p>\n\u003cp>现在题设给出包含映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i:L\\hookrightarrow D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 零伦。取同伦\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ni\\simeq c_{d_0}:L\\to D,\\qquad c_{d_0}(x)=d_0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nY=C(i)\\simeq C(c_{d_0}).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而常值映射的映射锥为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC(c_{d_0})\n =D\\cup_{L\\to\\{d_0\\}}CL\n \\cong D\\vee (CL/L),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">CL/L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是把锥底 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 缩成一点。它正是非约化悬挂 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：锥顶和锥底分别给出两个悬挂极点。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{Y\\simeq D\\vee\\Sigma L.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>楔点取为：\u003c/p>\n\u003cul>\n\u003cli>在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中取零伦终点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中取由锥底 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 缩成的那个极点。\u003c/li>\n\u003c/ul>\n\u003cp>若已另给 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的基点，利用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通，可沿路径把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 移到该基点；相应的常值映射也同伦。\u003c/p>\n\u003chr>\n\u003ch2>S3 整数扭结的实例\u003c/h2>\n\u003cp>设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb{RP}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一有限单纯三角剖分。取两个新顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u,v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，构造双锥\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=(u*L)\\cup_L(v*L).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其几何实现就是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX=|K|\\cong\\Sigma|L|\\cong\\Sigma\\mathbb{RP}^2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u,v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是两个悬挂极点。\u003c/p>\n\u003cp>任取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的一个顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为由边 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{v,w\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其两个端点组成的子复形。\u003c/p>\n\u003ch3>验证原条件\u003c/h3>\n\u003cp>把每个含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的重心坐标线性推到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到强形变收缩\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo>↘\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\setminus\\{v\\}\\ \\searrow\\ |u*L|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n后者是一个锥，因而可缩；同时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\setminus\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空。\u003c/p>\n\u003cp>另一方面，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>C\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC=|B|\\cong[0,1],\\qquad C\\setminus\\{v\\}\\cong(0,1].\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n二者均可缩，所以包含\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo>∩\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>↪\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nO\\cap C=C\\setminus\\{v\\}\\hookrightarrow C\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是同伦等价。\u003c/p>\n\u003ch3>同调与不可缩性\u003c/h3>\n\u003cp>非约化悬挂满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>Z\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Z\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_{n+1}(\\Sigma Z;R)\\cong\\widetilde H_n(Z;R).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_*(\\mathbb{RP}^2;\\mathbb Q)=0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\widetilde H_*(X;\\mathbb Q)=0.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n但\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH_2(X;\\mathbb Z)\n \\cong H_1(\\mathbb{RP}^2;\\mathbb Z)\n \\cong\\mathbb Z/2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可缩。这样便得到满足全部要求的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(K,v,B)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003chr>\n\u003ch2>S4 整体对象与全部恢复目标\u003c/h2>\n\u003ch3>1. 由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的局部数据分解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h3>\n\u003cp>定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK_0=\\{\\sigma\\in K:v\\notin\\sigma\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n以及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的链环\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>∪\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{lk}_K(v)\n =\\{\\tau\\in K_0:\\tau\\cup\\{v\\}\\in K\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nQ=|K_0|,\\qquad \\Lambda=|\\operatorname{lk}_K(v)|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的闭星形就是抽象锥 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v*\\operatorname{lk}_K(v)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∪\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=K_0\\cup(v*\\operatorname{lk}_K(v)),\\qquad\nK_0\\cap(v*\\operatorname{lk}_K(v))=\\operatorname{lk}_K(v).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当链环非空时，这在几何实现上给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/msub>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nX=Q\\cup_\\Lambda C\\Lambda. \\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>还有一个关键的强形变收缩\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo>↘\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>Q\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nO=X\\setminus\\{v\\}\\ \\searrow\\ Q. \\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n具体地，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 位于单形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v*\\tau\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中，写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>τ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>λ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nx=\\lambda v+(1-\\lambda)y,\\qquad y\\in|\\tau|,\\quad \\lambda\u0026lt;1,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmi>v\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmi>y\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nR_s(x)=(1-s)\\lambda v+\\bigl(1-(1-s)\\lambda\\bigr)y.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在不含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形上令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R_s=\\operatorname{id}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。该公式在面上相容，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R_1(O)\\subseteq Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故证明 (2)。\u003c/p>\n\u003cp>因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也是非空可缩有限 CW 复形。\u003c/p>\n\u003ch3>2. \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的所有可能同伦类型\u003c/h3>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{lk}_K(v)\\neq\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则在 (1) 中，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到可缩空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的包含必零伦。S2 的条件全部满足，因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\simeq Q\\vee\\Sigma\\Lambda.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n再把可缩子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 用 S1 缩商，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{X\\simeq\\Sigma\\Lambda\n =\\Sigma|\\operatorname{lk}_K(v)|.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>题设中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 还排除了链环为空的情形。事实上，若链环为空，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的孤立顶点。任何含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⊔\u003c/mo>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>C\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC=\\{v\\}\\sqcup C\u0026#x27;,\\qquad C\\setminus\\{v\\}=C\u0026#x27;,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可能为空。包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo>↪\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⊔\u003c/mo>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u0026#x27;\\hookrightarrow\\{v\\}\\sqcup C\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可能在路径分支集合上诱导双射，因而不可能是同伦等价。\u003c/p>\n\u003cp>故在原假设下，必有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{lk}_K(v)\\neq\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmi>X\u003c/mi>\u003c/mstyle>\u003cmtext> 的可能同伦类型恰为非空有限单纯复形的非约化悬挂。\u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\text{\\(X\\) 的可能同伦类型恰为非空有限单纯复形的非约化悬挂。}}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch3>3. 所有类型的实现\u003c/h3>\n\u003cp>任给非空有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取双锥\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=(u*L)\\cup_L(v*L).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\cong\\Sigma|L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且如 S3 所述，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo>↘\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\setminus\\{v\\}\\ \\searrow\\ |u*L|\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\setminus\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为边 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{v,w\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其面。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>C\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC\\cong[0,1],\\qquad C\\setminus\\{v\\}\\cong(0,1],\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo>∩\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">O\\cap C\\hookrightarrow C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是同伦等价。这样，每一个非空有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的悬挂类型都能实现。\u003c/p>\n\u003ch3>4. 可缩性的有限局部判据\u003c/h3>\n\u003cp>\u003cstrong>判据：\u003c/strong>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>X\u003c/mi>\u003cmtext> 可缩\u003c/mtext>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmtext> 且 \u003c/mtext>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>对所有 \u003c/mtext>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nX\\text{ 可缩}\n\\iff\n\\operatorname{lk}_K(v)\\neq\\varnothing\n\\ \\text{且}\\\n\\widetilde H_j(\\operatorname{lk}_K(v);\\mathbb Z)=0\n\\quad\\text{对所有 }j\\ge0.\n}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n也就是说，链环必须是\u003cstrong>非空、连通且整数无环的\u003c/strong>；其中连通性已包含在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde H_0=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中。\u003c/p>\n\u003cp>证明如下。记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda=|\\operatorname{lk}_K(v)|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\simeq\\Sigma\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及悬挂同调公式，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可缩，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_j(\\Lambda;\\mathbb Z)\n\\cong\\widetilde H_{j+1}(X;\\mathbb Z)=0\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立。\u003c/p>\n\u003cp>反之，若这些群全为零，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde H_0(\\Lambda)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通。非约化悬挂可用两个可缩的开锥邻域覆盖，其交同伦等价于路径连通的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；由 Seifert–van Kampen 定理，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 单连通。同时悬挂公式表明它整数无环。\u003c/p>\n\u003cp>单连通 CW 复形若所有约化整数同调均为零，则由 Hurewicz 定理逐次得到所有同伦群为零，再由 Whitehead 定理知其可缩。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\simeq\\Sigma\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可缩。\u003c/p>\n\u003cp>最后，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{lk}_K(v)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 完全由含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形及其面确定；其整数单纯同调可由有限个整数边界矩阵及其 Smith 标准形计算。因此这确实是一个只使用所要求局部有限关联数据的判据。\u003cstrong>必须取整数系数；有理无环并不足够，S3 就是反例。\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2>S5 不提供子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h2>\n\u003cp>\u003cstrong>结论：不必同伦等价于非空有限复形的悬挂。\u003c/strong>\u003c/p>\n\u003cp>最简单的反例是令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 只含两个孤立顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v,w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\setminus\\{v\\}=\\{w\\}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n非空可缩，但 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是两点离散空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。任何非空空间的非约化悬挂都路径连通，所以不可能同伦等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>完整分类仍由 S4 的分解得到：\u003c/p>\n\u003col>\n\u003cli>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{lk}_K(v)\\neq\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，不需要任何 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，仍有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\simeq\\Sigma|\\operatorname{lk}_K(v)|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003c/li>\n\u003cli>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{lk}_K(v)=\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 孤立，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmo>⊔\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|=Q\\sqcup\\{v\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo>⊔\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\simeq *\\sqcup *\\cong S^0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>反之，任取非空有限可缩单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>Z\u003c/mi>\u003cmo>⊔\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K=Z\\sqcup\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即可实现第二类情形。\u003c/p>\n\u003cp>所以没有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\u003cstrong>只新增一个同伦类型，即两点离散空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>；它恰好对应于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为孤立顶点。\u003c/p>\n\u003chr>\n\u003ch2>S6 悬挂信息的逆向恢复\u003c/h2>\n\u003cp>\u003cstrong>结论：不能推出。\u003c/strong>\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为单顶点复形，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|L_1|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是一个区间，因而可缩。\u003c/p>\n\u003cp>再取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr P\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Poincaré 同调 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-球面，去掉一个开 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-球，得到带边界的紧致流形\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmi mathvariant=\"normal\">int\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nN=\\mathscr P\\setminus\\operatorname{int}D^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一有限单纯三角剖分作为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 具有以下性质：\u003c/p>\n\u003cul>\n\u003cli>由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo>∪\u003c/mo>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr P=N\\cup D^3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>∩\u003c/mo>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\\cap D^3=S^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 van Kampen 定理，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_1(N)\\cong\\pi_1(\\mathscr P),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n后者是非平凡的二元二十面体群，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可缩。\u003c/li>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整数无环。事实上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_3(N)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有非空边界；同一拼接的 Mayer–Vietoris 序列给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover>\u003cmo stretchy=\"true\" minsize=\"3.0em\">→\u003c/mo>\u003cmpadded width=\"+0.6em\" lspace=\"0.3em\">\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmo>≅\u003c/mo>\u003cmtext> \u003c/mtext>\u003c/mrow>\u003c/mpadded>\u003c/mover>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH_3(\\mathscr P)\\xrightarrow{\\ \\cong\\ }H_2(S^2)\n\\longrightarrow H_2(N)\\longrightarrow H_2(\\mathscr P)=0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中连接映射把基本类送到边界球面的基本类，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_2(N)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。又有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"script\">P\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_1(N)=H_1(\\mathscr P)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连通。\u003c/li>\n\u003c/ul>\n\u003cp>于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通且整数无环。由 S4 中同样的 Hurewicz–Whitehead 论证，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|L_2|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 单连通且无环，所以可缩。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma|L_1|\\simeq *\\simeq\\Sigma|L_2|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n但是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo>≄\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|L_1|\\simeq *,\\qquad |L_2|\\simeq N\\not\\simeq *,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为二者基本群不同。故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo>⇏\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\Sigma|L_1|\\simeq\\Sigma|L_2|\\ \\not\\Rightarrow\\ |L_1|\\simeq|L_2|.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n","source":"assets/content/2e0a7d1226deadcb68635ddee7e9d83a22ba52f85bd83cf2515519ebd9af1fca.html"});
